item.command:
/bin/bash -lc "timeout 40s python - <<'PY'
import urllib.request
for u in ['https://raw.githubusercontent.com/akiyamalab/MEGADOCK/9575280c875732553266e26adc607dd892b02616/doc/README.md','https://raw.githubusercontent.com/akiyamalab/MEGADOCK/9575280c875732553266e26adc607dd892b02616/doc/BUILD.md']:
 print('URL',u)
 try:
  print(urllib.request.urlopen(u,timeout=15).read().decode())
 except Exception as e: print(type(e).__name__,str(e))
PY"

